const input = $input.first().json;
const body = input.body && typeof input.body === 'object' ? input.body : {};
const eventData = body.data && typeof body.data === 'object' ? body.data : {};
const source = { ...body, ...eventData };
const waValue = body.entry?.[0]?.changes?.[0]?.value || {};
const waMessage = waValue.messages?.[0] || {};

const rawCustomerId = source.customer_id ?? source.customerId ?? source.from ?? source.phone ?? waMessage.from ?? input.customer_id ?? input.from ?? '';
let customerId = String(rawCustomerId).replace(/\D/g, '');
if (customerId.startsWith('01') && customerId.length === 11) customerId = '88' + customerId;
const validCustomer = customerId.length >= 7 && customerId.length <= 15;

const rawMessage = source.message ?? source.text?.body ?? source.text ?? waMessage.text?.body ?? waMessage.button?.text ?? waMessage.interactive?.button_reply?.title ?? waMessage.interactive?.list_reply?.title ?? input.message ?? '';
const fullMessage = String(rawMessage).trim();
const mediaPayload = Boolean(source.has_media || source.ocr_text || source.ocrText || source.media_url || source.mediaUrl || source.media_type || source.mimeType);
const maxMessageLength = mediaPayload ? 12000 : 2000;
const message = fullMessage.slice(0, maxMessageLength);
const messageId = String(source.message_id ?? source.messageId ?? waMessage.id ?? input.message_id ?? '').trim();

// Check repetitive spam flood
const isSpamFlood = /(.)\1{7,}/i.test(message);
const isEmpty = message.length === 0;
const isTooLong = fullMessage.length > maxMessageLength;

let spam_status = 'CLEAN';
if (isSpamFlood) spam_status = 'SPAM_REPETITIVE';
else if (isEmpty) spam_status = 'EMPTY_PAYLOAD';
else if (isTooLong) spam_status = 'PAYLOAD_OVERSIZED';

return [{
  json: {
    ...input,
    source,
    body,
    customerId,
    validCustomer,
    rawMessage,
    fullMessage,
    mediaPayload,
    maxMessageLength,
    message,
    messageId,
    spam_status,
    is_spam: spam_status !== 'CLEAN'
  }
}];

const item = $input.first().json;
let text = item.message;

// Dialect Normalization
const dialectMap = {
  'আঁই': 'আমি',
  'আঁর': 'আমার',
  'হনেন': 'শুনেন',
  'হগল': 'সব',
  'হেইডা': 'সেটা',
  'মুই': 'আমি',
  'মোর': 'আমার',
  'তোগো': 'তোমাদের',
  'আইজকা': 'আজকে',
  'কাইলকা': 'কালকে',
  'কও': 'বল',
  'কইন': 'বলেন',
  'কিসেরলাইগা': 'কেন',
  'ক্যান': 'কেন'
};

for (const [dialect, standard] of Object.entries(dialectMap)) {
  text = text.replace(new RegExp(dialect, 'gu'), standard);
}

// Banglish Phonetic Token Normalization
const lower = text.toLowerCase();
const tokens = lower.match(/[a-z0-9]+/g) || [];
const tokenSet = new Set(tokens);
const containsBengali = /[\u0980-\u09ff]/u.test(text);
const hasAnyToken = (words) => words.some((word) => tokenSet.has(String(word).toLowerCase()));

const banglishWords = ['ami', 'amar', 'amader', 'apni', 'apnar', 'ki', 'koto', 'kaj', 'dorkar', 'chai', 'chacchi', 'ase', 'ache', 'nai', 'lagbe', 'bolben', 'diben', 'pathabo', 'kagoj', 'vul', 'thik', 'jonno', 'ektu', 'kora', 'korbo', 'hoy', 'hobe', 'kobe', 'taka', 'dam', 'nam', 'purono', 'eta', 'seta', 'sathe', 'niye', 'jante', 'bujhiye', 'puro', 'poddhoti', 'suru', 'shuru', 'bhai', 'vai', 'parben', 'somoy', 'shomoy', 'online', 'pdf', 'delivery', 'jonmo', 'nibondhon', 'janmo', 'bacha', 'baccha', 'shishu', 'dhaka', 'city', 'zone', 'sonshodhon', 'shongshodhon', 'ctg', 'chittagong', 'chattogram', 'mongolbar', 'tuesday', 'seller', 'vendor', 'file', 'customer', 'din', '1din', '2002', '2012', 'passport', 'nid'];
const grammarWords = ['i', 'we', 'you', 'my', 'our', 'your', 'the', 'am', 'is', 'are', 'was', 'were', 'do', 'does', 'can', 'could', 'would', 'will', 'what', 'which', 'where', 'when', 'why', 'how', 'need', 'want', 'please', 'help', 'tell', 'provide'];
const grammarScore = tokens.filter((token) => grammarWords.includes(token)).length;

let replyLanguage = 'bn';
if (item.source.reply_language === 'en' || item.source.reply_language === 'bn') {
  replyLanguage = item.source.reply_language;
} else if (containsBengali || hasAnyToken(banglishWords)) {
  replyLanguage = 'bn';
} else if (tokens.length >= 3 && grammarScore >= 1) {
  replyLanguage = 'en';
}

return [{
  json: {
    ...item,
    normalized_message: text,
    reply_language: replyLanguage,
    tokens,
    tokenSet: Array.from(tokenSet)
  }
}];

const item = $input.first().json;
const message = item.normalized_message;
const lower = message.toLowerCase();

// Deep Security & Jailbreak Inspection
const injectionPhrases = ['ignore previous', 'ignore all instructions', 'system prompt', 'developer message', 'jailbreak', 'reveal instructions', 'system password', 'আগের নির্দেশনা ভুলে'];
const isPromptInjection = injectionPhrases.some(p => lower.includes(p));

// Sensitive & Risky Keywords
const riskyPhrases = ['payment dispute', 'payment problem', 'account hacked', 'money back', 'fake service'];
const riskyTokens = ['refund', 'rifand', 'ferot', 'complaint', 'ovijog', 'scam', 'fraud', 'legal', 'ain', 'case', 'mamla', 'medical', 'doctor', 'hacked'];
const riskyBengali = ['ফেরত', 'অভিযোগ', 'প্রতারণা', 'আইন', 'মামলা', 'পেমেন্ট সমস্যা', 'হ্যাক', 'টাকা ফেরত'];

const isRisky = riskyPhrases.some(p => lower.includes(p)) || riskyTokens.some(t => item.tokenSet.includes(t)) || riskyBengali.some(b => message.includes(b));
const customerRef = item.validCustomer ? '***' + item.customerId.slice(-4) : '';

return [{
  json: {
    ...item,
    is_prompt_injection: isPromptInjection,
    is_risky: isRisky,
    customer_ref: customerRef
  }
}];

const item = $input.first().json;
const message = item.normalized_message;
const lower = message.toLowerCase();
const tokenSet = new Set(item.tokenSet || []);

// Urgency Indicators
const urgentTokens = ['urgent', 'emergency', 'khub', 'taratari', 'ajkei', 'ekhoni', 'druto', 'জরুরি', 'তাড়াতাড়ি', 'আজকেই', 'এখনই', 'দ্রুত'];
const isUrgent = urgentTokens.some(t => lower.includes(t));

// Sentiment Analysis
let sentiment = 'neutral';
const negativeTokens = ['angry', 'bad', 'kharap', 'faltu', 'baje', 'cheat', 'scam', 'fraud', 'chor', 'dhoka', 'rag', 'ovijog', 'ferot'];
const positiveTokens = ['thanks', 'dhonnobad', 'valo', 'good', 'great', 'shundor', 'bhalo', 'satisfied'];
if (negativeTokens.some(t => tokenSet.has(t)) || ['বাজে', 'খারাপ', 'প্রতারক', 'ধোঁকা', 'রাগ', 'অভিযোগ'].some(b => message.includes(b))) {
  sentiment = 'negative';
} else if (positiveTokens.some(t => tokenSet.has(t)) || ['ধন্যবাদ', 'ভালো', 'সুন্দর'].some(b => message.includes(b))) {
  sentiment = 'positive';
}

// VIP Lead Scoring
let urgency_score = isUrgent ? 9 : (sentiment === 'negative' ? 8 : 5);
let lead_tier = 'STANDARD_INQUIRY';
if (lower.includes('payment') || lower.includes('paid') || lower.includes('trx') || lower.includes('টাকা')) {
  lead_tier = 'HOT_PAYMENT_LEAD';
  urgency_score = 10;
} else if (isUrgent) {
  lead_tier = 'VIP_URGENT_LEAD';
} else if (sentiment === 'negative') {
