const isDhaka = lower.includes('dhaka') || lower.includes('ঢাকা');
const isCorrection = lower.includes('সংশোধন') || lower.includes('correction') || lower.includes('vul') || lower.includes('ভুল') || lower.includes('thik') || lower.includes('ঠিক');

if (lower.includes('birth') || lower.includes('jonmo') || lower.includes('janmo') || lower.includes('জন্ম') || lower.includes('নিবন্ধন') || lower.includes('nibondhon') || lower.includes('বাচ্চা') || lower.includes('shishu')) {
  if (isCtg && !isCorrection) {
    service_category = 'Chattogram City New Birth Registration (চট্টগ্রাম সিটি নতুন নিবন্ধন - প্রতি মঙ্গলবার)';
    service_code = 'SRV_CTG_NEW_BIRTH';
    digital_delivery_time = 'Every Tuesday (প্রতি মঙ্গলবার অনলাইন প্রসেস ও WhatsApp PDF)';
    specialist_persona = 'ctg_birth_specialist';
