const data = $input.first().json;
const routed = $('Needs DeepSeek AI?').first().json;
const english = routed.reply_language === 'en';
const languageFallback = english
  ? 'Thank you for your message. Please share which online service you need, and our team will confirm the required documents, fee and expected completion time.'
  : 'আপনার বার্তার জন্য ধন্যবাদ। কোন অনলাইন সেবাটি নিতে চান জানালে প্রয়োজনীয় কাগজপত্র, খরচ ও সম্ভাব্য ডেলিভারির সময় জানিয়ে দেব।';
const failureFallback = english
  ? 'Sorry, our automated service is temporarily busy. A team member will review your message and reply via WhatsApp as soon as possible.'
  : 'দুঃখিত, আমাদের সাপোর্ট টিম একটু ব্যস্ত। কিছুক্ষণের মধ্যেই আপনার মেসেজ দেখে WhatsApp-এ উত্তর দিচ্ছি।';

const sanitizeReply = (value) => String(value || '')
  .replace(/\*\*(.*?)\*\*/gu, '$1')
  .replace(/^\s{0,3}#{1,6}\s*/gmu, '')
  .replace(/^\s*(?:[-*•]|📌|\d+[.)])\s*/gmu, '')
  .replace(/\n{3,}/gu, '\n\n')
  .trim();

const enforceLanguage = (value) => {
  let clean = sanitizeReply(value);
  if (english) return /[\u0980-\u09ff]/u.test(clean) ? languageFallback : clean;

  const officialTerms = [
    ['e-TIN', '__OFFICIAL_ETIN__'],
    ['bKash', '__OFFICIAL_BKASH__'],
    ['Nagad', '__OFFICIAL_NAGAD__'],
    ['NID', '__OFFICIAL_NID__'],
    ['TIN', '__OFFICIAL_TIN__'],
    ['PDF', '__OFFICIAL_PDF__'],
    ['OTP', '__OFFICIAL_OTP__'],
    ['SMS', '__OFFICIAL_SMS__'],
    ['WhatsApp', '__OFFICIAL_WA__'],
    ['TrxID', '__OFFICIAL_TRXID__'],
    ['Dhaka', '__OFFICIAL_DHAKA__'],
    ['Chattogram', '__OFFICIAL_CTG__'],
    ['CTG', '__OFFICIAL_CTG__'],
    ['City', '__OFFICIAL_CITY__'],
    ['Tuesday', '__OFFICIAL_TUESDAY__']
  ];
  for (const [term, placeholder] of officialTerms) {
    clean = clean.replace(new RegExp(term, 'giu'), placeholder);
  }

  const commonReplacements = {
    needed: 'প্রয়োজন',
    need: 'প্রয়োজন',
    document: 'কাগজপত্র',
    documents: 'কাগজপত্র',
    certificate: 'সনদ',
    certificates: 'সনদ',
    service: 'সেবা',
    services: 'সেবা',
    process: 'প্রক্রিয়া',
    price: 'মূল্য',
    cost: 'খরচ',
    time: 'সময়',
    team: 'দল',
    payment: 'টাকা',
    status: 'অবস্থা',
    file: 'কাগজপত্র',
    files: 'কাগজপত্র',
    form: 'ফরম',
    online: 'অনলাইন',
    representative: 'প্রতিনিধি'
  };
  for (const [source, replacement] of Object.entries(commonReplacements)) {
    clean = clean.replace(new RegExp('\\b' + source + '\\b', 'giu'), replacement);
  }
  clean = clean
    .replace(/ডকুমেন্ট(?:স)?/gu, 'কাগজপত্র')
    .replace(/সার্টিফিকেট/gu, 'সনদ')
    .replace(/হেল্প/gu, 'সাহায্য');

  for (const [term, placeholder] of officialTerms) {
    clean = clean.replaceAll(placeholder, term);
  }
  return clean || languageFallback;
};

const limitReply = (value, maxCharacters = 320) => {
  const clean = enforceLanguage(value);
  const characters = Array.from(clean);
  if (characters.length <= maxCharacters) return clean;
  const preview = characters.slice(0, maxCharacters).join('');
  const boundaries = [...preview.matchAll(/[।.!?](?:\s|$)/gu)];
  const lastBoundary = boundaries.at(-1);
  if (lastBoundary && lastBoundary.index >= 40) {
    return preview.slice(0, lastBoundary.index + lastBoundary[0].length).trim();
  }
  return characters.slice(0, maxCharacters - 1).join('').trimEnd() + '…';
};

const generated = String(data.output || data.text || data.response || '').trim();
const failed = Boolean(data.error) || !generated;
const reply = failed ? failureFallback : limitReply(generated);

return [{
  json: {
    success: !failed,
    reply,
    confidence: failed ? 0 : 0.95,
    used_deepseek: true,
    handoff: failed,
    intent: failed ? 'ai_error_handoff' : 'digital_ai_consultation',
    specialist_persona: routed.specialist_persona,
    sentiment: routed.sentiment,
    lead_tier: routed.lead_tier,
    urgency_score: routed.urgency_score,
    service_category: routed.service_category,
    priority_level: routed.urgency_score >= 8 ? 'HIGH' : 'NORMAL',
    reason: failed ? 'deepseek_unavailable' : 'deepseek_ai_agent',
    service_code: routed.service_code,
    customer_id: routed.customerId,
    customer_ref: routed.customer_ref,
    entities: routed.entities || {},
    match_readiness: routed.match_readiness || {},
    missing_fields: routed.match_readiness?.missing_fields || [],
    message_id: routed.messageId,
  }
}];

